import{_ as r,o as d,c as o,at as e}from"./chunks/framework.CY22Hent.js";const u=JSON.parse('{"title":"软件设计师笔记14_英语","description":"","frontmatter":{"title":"软件设计师笔记14_英语","date":"2026-05-18T00:00:00.000Z","lastupdated":"2026-05-18T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/软件设计师笔记14_英语.md","filePath":"blogs/软考/软件设计师笔记14_英语.md"}'),n={name:"blogs/软考/软件设计师笔记14_英语.md"};function a(s,t,i,l,g,h){return d(),o("div",null,[...t[0]||(t[0]=[e('<p>[toc]</p><h1 id="软件设计师笔记14-英语" tabindex="-1">软件设计师笔记14_英语 <a class="header-anchor" href="#软件设计师笔记14-英语" aria-label="Permalink to &quot;软件设计师笔记14_英语&quot;">​</a></h1><h2 id="一、考试形式与分值" tabindex="-1">一、考试形式与分值 <a class="header-anchor" href="#一、考试形式与分值" aria-label="Permalink to &quot;一、考试形式与分值&quot;">​</a></h2><p>软考软件设计师考试中，专业英语部分位于上午选择题的最后5题（第71-75题），每题1分，共5分。</p><p><strong>考试形式</strong>：一篇英文短文（约150-200词），包含5个空白处，每个空白处有4个选项，选择最合适的词汇填入。</p><p><strong>考察重点</strong>：</p><ul><li>计算机专业词汇认知</li><li>上下文语义理解</li><li>固定搭配和常用表达</li><li>基本语法知识（时态、语态、从句等）</li></ul><p><strong>难度等级</strong>：中等偏易，词汇难度相当于大学英语四级，但侧重计算机专业领域。</p><hr><h2 id="二、高频词汇分类汇总" tabindex="-1">二、高频词汇分类汇总 <a class="header-anchor" href="#二、高频词汇分类汇总" aria-label="Permalink to &quot;二、高频词汇分类汇总&quot;">​</a></h2><h3 id="_1-软件工程类" tabindex="-1">1. 软件工程类 <a class="header-anchor" href="#_1-软件工程类" aria-label="Permalink to &quot;1. 软件工程类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>英文词汇</th><th>中文含义</th><th>常见搭配</th></tr></thead><tbody><tr><td><strong>Agile</strong></td><td>敏捷的</td><td>Agile Development（敏捷开发）</td></tr><tr><td><strong>Waterfall</strong></td><td>瀑布</td><td>Waterfall Model（瀑布模型）</td></tr><tr><td><strong>Iterative</strong></td><td>迭代的</td><td>Iterative Development（迭代开发）</td></tr><tr><td><strong>Incremental</strong></td><td>增量的</td><td>Incremental Model（增量模型）</td></tr><tr><td><strong>Prototype</strong></td><td>原型</td><td>Prototype Method（原型法）</td></tr><tr><td><strong>Requirement</strong></td><td>需求</td><td>Requirement Analysis（需求分析）</td></tr><tr><td><strong>Design</strong></td><td>设计</td><td>System Design（系统设计）</td></tr><tr><td><strong>Implementation</strong></td><td>实现</td><td>Implementation Phase（实现阶段）</td></tr><tr><td><strong>Testing</strong></td><td>测试</td><td>Testing Strategy（测试策略）</td></tr><tr><td><strong>Maintenance</strong></td><td>维护</td><td>Maintenance Phase（维护阶段）</td></tr><tr><td><strong>Bug</strong></td><td>缺陷</td><td>Bug Fix（修复缺陷）</td></tr><tr><td><strong>Debugging</strong></td><td>调试</td><td>Debugging Tool（调试工具）</td></tr><tr><td><strong>Version</strong></td><td>版本</td><td>Version Control（版本控制）</td></tr><tr><td><strong>Release</strong></td><td>发布</td><td>Release Management（发布管理）</td></tr><tr><td><strong>Document</strong></td><td>文档</td><td>Technical Document（技术文档）</td></tr></tbody></table><h3 id="_2-面向对象类" tabindex="-1">2. 面向对象类 <a class="header-anchor" href="#_2-面向对象类" aria-label="Permalink to &quot;2. 面向对象类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>英文词汇</th><th>中文含义</th><th>常见搭配</th></tr></thead><tbody><tr><td><strong>Class</strong></td><td>类</td><td>Abstract Class（抽象类）</td></tr><tr><td><strong>Object</strong></td><td>对象</td><td>Object-Oriented（面向对象）</td></tr><tr><td><strong>Inheritance</strong></td><td>继承</td><td>Single Inheritance（单继承）</td></tr><tr><td><strong>Polymorphism</strong></td><td>多态</td><td>Polymorphism（多态性）</td></tr><tr><td><strong>Encapsulation</strong></td><td>封装</td><td>Data Encapsulation（数据封装）</td></tr><tr><td><strong>Abstraction</strong></td><td>抽象</td><td>Data Abstraction（数据抽象）</td></tr><tr><td><strong>Interface</strong></td><td>接口</td><td>Interface Design（接口设计）</td></tr><tr><td><strong>Method</strong></td><td>方法</td><td>Class Method（类方法）</td></tr><tr><td><strong>Attribute</strong></td><td>属性</td><td>Class Attribute（类属性）</td></tr><tr><td><strong>Instance</strong></td><td>实例</td><td>Class Instance（类实例）</td></tr><tr><td><strong>Constructor</strong></td><td>构造函数</td><td>Default Constructor（默认构造函数）</td></tr><tr><td><strong>Destructor</strong></td><td>析构函数</td><td>Virtual Destructor（虚析构函数）</td></tr><tr><td><strong>Override</strong></td><td>重写</td><td>Method Override（方法重写）</td></tr><tr><td><strong>Overload</strong></td><td>重载</td><td>Method Overload（方法重载）</td></tr><tr><td><strong>Encapsulation</strong></td><td>封装</td><td>Information Hiding（信息隐藏）</td></tr></tbody></table><h3 id="_3-数据库类" tabindex="-1">3. 数据库类 <a class="header-anchor" href="#_3-数据库类" aria-label="Permalink to &quot;3. 数据库类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>英文词汇</th><th>中文含义</th><th>常见搭配</th></tr></thead><tbody><tr><td><strong>Database</strong></td><td>数据库</td><td>Relational Database（关系型数据库）</td></tr><tr><td><strong>Table</strong></td><td>表</td><td>Database Table（数据库表）</td></tr><tr><td><strong>Column</strong></td><td>列</td><td>Table Column（表列）</td></tr><tr><td><strong>Row</strong></td><td>行</td><td>Data Row（数据行）</td></tr><tr><td><strong>Primary Key</strong></td><td>主键</td><td>Primary Key Constraint（主键约束）</td></tr><tr><td><strong>Foreign Key</strong></td><td>外键</td><td>Foreign Key Constraint（外键约束）</td></tr><tr><td><strong>Index</strong></td><td>索引</td><td>Create Index（创建索引）</td></tr><tr><td><strong>Query</strong></td><td>查询</td><td>SQL Query（SQL查询）</td></tr><tr><td><strong>Transaction</strong></td><td>事务</td><td>Transaction Management（事务管理）</td></tr><tr><td><strong>Normalization</strong></td><td>规范化</td><td>Database Normalization（数据库规范化）</td></tr><tr><td><strong>Schema</strong></td><td>模式</td><td>Database Schema（数据库模式）</td></tr><tr><td><strong>View</strong></td><td>视图</td><td>Database View（数据库视图）</td></tr><tr><td><strong>Stored Procedure</strong></td><td>存储过程</td><td>Execute Procedure（执行存储过程）</td></tr><tr><td><strong>Trigger</strong></td><td>触发器</td><td>Database Trigger（数据库触发器）</td></tr><tr><td><strong>Join</strong></td><td>连接</td><td>Inner Join（内连接）</td></tr></tbody></table><h3 id="_4-网络与安全类" tabindex="-1">4. 网络与安全类 <a class="header-anchor" href="#_4-网络与安全类" aria-label="Permalink to &quot;4. 网络与安全类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>英文词汇</th><th>中文含义</th><th>常见搭配</th></tr></thead><tbody><tr><td><strong>Protocol</strong></td><td>协议</td><td>Network Protocol（网络协议）</td></tr><tr><td><strong>TCP/IP</strong></td><td>传输控制协议/网际协议</td><td>TCP/IP Protocol Suite（TCP/IP协议簇）</td></tr><tr><td><strong>HTTP</strong></td><td>超文本传输协议</td><td>HTTP Request（HTTP请求）</td></tr><tr><td><strong>HTTPS</strong></td><td>安全超文本传输协议</td><td>HTTPS Connection（HTTPS连接）</td></tr><tr><td><strong>Firewall</strong></td><td>防火墙</td><td>Network Firewall（网络防火墙）</td></tr><tr><td><strong>Encryption</strong></td><td>加密</td><td>Data Encryption（数据加密）</td></tr><tr><td><strong>Decryption</strong></td><td>解密</td><td>Data Decryption（数据解密）</td></tr><tr><td><strong>Authentication</strong></td><td>认证</td><td>User Authentication（用户认证）</td></tr><tr><td><strong>Authorization</strong></td><td>授权</td><td>Access Authorization（访问授权）</td></tr><tr><td><strong>Malware</strong></td><td>恶意软件</td><td>Malware Detection（恶意软件检测）</td></tr><tr><td><strong>Virus</strong></td><td>病毒</td><td>Computer Virus（计算机病毒）</td></tr><tr><td><strong>Hacker</strong></td><td>黑客</td><td>Hacker Attack（黑客攻击）</td></tr><tr><td><strong>LAN</strong></td><td>局域网</td><td>Local Area Network（局域网）</td></tr><tr><td><strong>WAN</strong></td><td>广域网</td><td>Wide Area Network（广域网）</td></tr><tr><td><strong>VPN</strong></td><td>虚拟专用网络</td><td>Virtual Private Network（虚拟专用网络）</td></tr></tbody></table><h3 id="_5-算法与数据结构类" tabindex="-1">5. 算法与数据结构类 <a class="header-anchor" href="#_5-算法与数据结构类" aria-label="Permalink to &quot;5. 算法与数据结构类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>英文词汇</th><th>中文含义</th><th>常见搭配</th></tr></thead><tbody><tr><td><strong>Algorithm</strong></td><td>算法</td><td>Algorithm Design（算法设计）</td></tr><tr><td><strong>Data Structure</strong></td><td>数据结构</td><td>Data Structure Analysis（数据结构分析）</td></tr><tr><td><strong>Array</strong></td><td>数组</td><td>One-dimensional Array（一维数组）</td></tr><tr><td><strong>Linked List</strong></td><td>链表</td><td>Singly Linked List（单链表）</td></tr><tr><td><strong>Stack</strong></td><td>栈</td><td>Push/Pop Operation（入栈/出栈操作）</td></tr><tr><td><strong>Queue</strong></td><td>队列</td><td>Enqueue/Dequeue（入队/出队）</td></tr><tr><td><strong>Tree</strong></td><td>树</td><td>Binary Tree（二叉树）</td></tr><tr><td><strong>Graph</strong></td><td>图</td><td>Directed Graph（有向图）</td></tr><tr><td><strong>Sort</strong></td><td>排序</td><td>Sorting Algorithm（排序算法）</td></tr><tr><td><strong>Search</strong></td><td>搜索</td><td>Search Algorithm（搜索算法）</td></tr><tr><td><strong>Recursion</strong></td><td>递归</td><td>Recursive Function（递归函数）</td></tr><tr><td><strong>Complexity</strong></td><td>复杂度</td><td>Time Complexity（时间复杂度）</td></tr><tr><td><strong>Divide</strong></td><td>分治</td><td>Divide and Conquer（分治法）</td></tr><tr><td><strong>Dynamic Programming</strong></td><td>动态规划</td><td>DP Algorithm（动态规划算法）</td></tr><tr><td><strong>Greedy</strong></td><td>贪心</td><td>Greedy Algorithm（贪心算法）</td></tr></tbody></table><h3 id="_6-操作系统类" tabindex="-1">6. 操作系统类 <a class="header-anchor" href="#_6-操作系统类" aria-label="Permalink to &quot;6. 操作系统类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>英文词汇</th><th>中文含义</th><th>常见搭配</th></tr></thead><tbody><tr><td><strong>Process</strong></td><td>进程</td><td>Process Management（进程管理）</td></tr><tr><td><strong>Thread</strong></td><td>线程</td><td>Multithreading（多线程）</td></tr><tr><td><strong>Memory</strong></td><td>内存</td><td>Memory Management（内存管理）</td></tr><tr><td><strong>CPU</strong></td><td>中央处理器</td><td>CPU Scheduling（CPU调度）</td></tr><tr><td><strong>File</strong></td><td>文件</td><td>File System（文件系统）</td></tr><tr><td><strong>I/O</strong></td><td>输入输出</td><td>I/O Operation（输入输出操作）</td></tr><tr><td><strong>Kernel</strong></td><td>内核</td><td>Operating System Kernel（操作系统内核）</td></tr><tr><td><strong>Shell</strong></td><td>外壳</td><td>Command Shell（命令行外壳）</td></tr><tr><td><strong>Synchronization</strong></td><td>同步</td><td>Process Synchronization（进程同步）</td></tr><tr><td><strong>Deadlock</strong></td><td>死锁</td><td>Deadlock Prevention（死锁预防）</td></tr><tr><td><strong>Semaphore</strong></td><td>信号量</td><td>Semaphore Mechanism（信号量机制）</td></tr><tr><td><strong>Mutex</strong></td><td>互斥锁</td><td>Mutex Lock（互斥锁）</td></tr><tr><td><strong>Interrupt</strong></td><td>中断</td><td>Interrupt Handling（中断处理）</td></tr><tr><td><strong>Virtual Memory</strong></td><td>虚拟内存</td><td>Virtual Memory Management（虚拟内存管理）</td></tr><tr><td><strong>Cache</strong></td><td>缓存</td><td>Cache Memory（高速缓存）</td></tr></tbody></table><h3 id="_7-软件测试类" tabindex="-1">7. 软件测试类 <a class="header-anchor" href="#_7-软件测试类" aria-label="Permalink to &quot;7. 软件测试类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>英文词汇</th><th>中文含义</th><th>常见搭配</th></tr></thead><tbody><tr><td><strong>Test</strong></td><td>测试</td><td>Software Testing（软件测试）</td></tr><tr><td><strong>Unit Test</strong></td><td>单元测试</td><td>Unit Testing Framework（单元测试框架）</td></tr><tr><td><strong>Integration Test</strong></td><td>集成测试</td><td>Integration Testing（集成测试）</td></tr><tr><td><strong>System Test</strong></td><td>系统测试</td><td>System Testing（系统测试）</td></tr><tr><td><strong>Acceptance Test</strong></td><td>验收测试</td><td>User Acceptance Test（用户验收测试）</td></tr><tr><td><strong>Black Box</strong></td><td>黑盒</td><td>Black Box Testing（黑盒测试）</td></tr><tr><td><strong>White Box</strong></td><td>白盒</td><td>White Box Testing（白盒测试）</td></tr><tr><td><strong>Regression</strong></td><td>回归</td><td>Regression Testing（回归测试）</td></tr><tr><td><strong>Performance</strong></td><td>性能</td><td>Performance Testing（性能测试）</td></tr><tr><td><strong>Bug</strong></td><td>缺陷</td><td>Bug Tracking（缺陷跟踪）</td></tr><tr><td><strong>Defect</strong></td><td>缺陷</td><td>Defect Management（缺陷管理）</td></tr><tr><td><strong>Coverage</strong></td><td>覆盖率</td><td>Code Coverage（代码覆盖率）</td></tr><tr><td><strong>Automation</strong></td><td>自动化</td><td>Test Automation（测试自动化）</td></tr><tr><td><strong>Load</strong></td><td>负载</td><td>Load Testing（负载测试）</td></tr><tr><td><strong>Stress</strong></td><td>压力</td><td>Stress Testing（压力测试）</td></tr></tbody></table><hr><h2 id="三、常考语法结构" tabindex="-1">三、常考语法结构 <a class="header-anchor" href="#三、常考语法结构" aria-label="Permalink to &quot;三、常考语法结构&quot;">​</a></h2><h3 id="_1-时态" tabindex="-1">1. 时态 <a class="header-anchor" href="#_1-时态" aria-label="Permalink to &quot;1. 时态&quot;">​</a></h3><ul><li><strong>一般现在时</strong>：用于描述事实、真理、习惯性动作</li><li><strong>现在进行时</strong>：用于描述正在进行的动作</li><li><strong>一般过去时</strong>：用于描述过去发生的动作</li><li><strong>一般将来时</strong>：用于描述将要发生的动作</li><li><strong>现在完成时</strong>：用于描述过去发生且对现在有影响的动作</li></ul><h3 id="_2-语态" tabindex="-1">2. 语态 <a class="header-anchor" href="#_2-语态" aria-label="Permalink to &quot;2. 语态&quot;">​</a></h3><ul><li><strong>主动语态</strong>：主语执行动作</li><li><strong>被动语态</strong>：主语承受动作（<code>be + 过去分词</code>）</li></ul><h3 id="_3-从句" tabindex="-1">3. 从句 <a class="header-anchor" href="#_3-从句" aria-label="Permalink to &quot;3. 从句&quot;">​</a></h3><ul><li><strong>定语从句</strong>：修饰名词（who, which, that, whose）</li><li><strong>状语从句</strong>：修饰动词、形容词或整个句子（when, if, because, although）</li><li><strong>名词性从句</strong>：在句中充当名词（主语从句、宾语从句、表语从句、同位语从句）</li></ul><h3 id="_4-非谓语动词" tabindex="-1">4. 非谓语动词 <a class="header-anchor" href="#_4-非谓语动词" aria-label="Permalink to &quot;4. 非谓语动词&quot;">​</a></h3><ul><li><strong>不定式</strong>（to + 动词原形）：表目的、将来</li><li><strong>动名词</strong>（动词+ing）：表主动、进行</li><li><strong>分词</strong>：现在分词表主动/进行，过去分词表被动/完成</li></ul><h3 id="_5-固定搭配" tabindex="-1">5. 固定搭配 <a class="header-anchor" href="#_5-固定搭配" aria-label="Permalink to &quot;5. 固定搭配&quot;">​</a></h3><ul><li><code>depend on</code>（依赖）</li><li><code>consist of</code>（由...组成）</li><li><code>be responsible for</code>（对...负责）</li><li><code>according to</code>（根据）</li><li><code>in order to</code>（为了）</li><li><code>such as</code>（例如）</li><li><code>due to</code>（由于）</li><li><code>lead to</code>（导致）</li><li><code>focus on</code>（专注于）</li><li><code>play a role in</code>（在...中起作用）</li></ul><hr><h2 id="四、做题技巧" tabindex="-1">四、做题技巧 <a class="header-anchor" href="#四、做题技巧" aria-label="Permalink to &quot;四、做题技巧&quot;">​</a></h2><h3 id="_1-通读全文-理解大意" tabindex="-1">1. 通读全文，理解大意 <a class="header-anchor" href="#_1-通读全文-理解大意" aria-label="Permalink to &quot;1. 通读全文，理解大意&quot;">​</a></h3><ul><li>先快速浏览全文，了解文章主题（软件工程、数据库、网络等）</li><li>注意文章的逻辑结构（总分、因果、对比等）</li></ul><h3 id="_2-分析空格前后语境" tabindex="-1">2. 分析空格前后语境 <a class="header-anchor" href="#_2-分析空格前后语境" aria-label="Permalink to &quot;2. 分析空格前后语境&quot;">​</a></h3><ul><li>注意空格前后的词汇搭配</li><li>分析句子结构，确定需要填的词性（名词、动词、形容词、副词等）</li></ul><h3 id="_3-排除法解题" tabindex="-1">3. 排除法解题 <a class="header-anchor" href="#_3-排除法解题" aria-label="Permalink to &quot;3. 排除法解题&quot;">​</a></h3><ul><li>先排除明显错误的选项</li><li>比较剩余选项，选择最符合语境的答案</li></ul><h3 id="_4-注意专业术语" tabindex="-1">4. 注意专业术语 <a class="header-anchor" href="#_4-注意专业术语" aria-label="Permalink to &quot;4. 注意专业术语&quot;">​</a></h3><ul><li>熟悉常见的计算机专业词汇</li><li>注意缩写词的全称和含义</li></ul><h3 id="_5-检查语法正确性" tabindex="-1">5. 检查语法正确性 <a class="header-anchor" href="#_5-检查语法正确性" aria-label="Permalink to &quot;5. 检查语法正确性&quot;">​</a></h3><ul><li>检查主谓一致</li><li>检查时态、语态是否正确</li><li>检查固定搭配是否恰当</li></ul><hr><h2 id="五、记忆点总结" tabindex="-1">五、记忆点总结 <a class="header-anchor" href="#五、记忆点总结" aria-label="Permalink to &quot;五、记忆点总结&quot;">​</a></h2><h3 id="_1-高频词汇记忆口诀" tabindex="-1">1. 高频词汇记忆口诀 <a class="header-anchor" href="#_1-高频词汇记忆口诀" aria-label="Permalink to &quot;1. 高频词汇记忆口诀&quot;">​</a></h3><blockquote><p><strong>软件工程</strong>： &quot;需求分析设计实现，测试维护版本控 敏捷迭代瀑布模，原型增量文档全&quot;</p></blockquote><blockquote><p><strong>面向对象</strong>： &quot;类和对象是基础，继承多态封装酷 接口方法属性全，重载重写要记住&quot;</p></blockquote><blockquote><p><strong>数据库</strong>： &quot;主键外键索引建，查询事务规范化 表行列视图存储，触发器和连接全&quot;</p></blockquote><blockquote><p><strong>网络安全</strong>： &quot;协议HTTP和TCP，加密认证防火墙 病毒黑客恶意软，LANWAN加VPN&quot;</p></blockquote><blockquote><p><strong>算法数据</strong>： &quot;数组链表栈队列，树图排序搜索全 递归分治动规划，贪心复杂度计算&quot;</p></blockquote><h3 id="_2-常考主题预测" tabindex="-1">2. 常考主题预测 <a class="header-anchor" href="#_2-常考主题预测" aria-label="Permalink to &quot;2. 常考主题预测&quot;">​</a></h3><p>根据历年真题分析，以下主题出现频率最高：</p><ol><li><strong>敏捷开发/DevOps</strong>：Agile, Scrum, DevOps, Sprint, Iteration</li><li><strong>云计算/虚拟化</strong>：Cloud, Virtualization, SaaS, PaaS, IaaS</li><li><strong>数据库技术</strong>：SQL, Transaction, Index, Normalization, Join</li><li><strong>软件测试</strong>：Testing, Bug, Defect, Regression, Automation</li><li><strong>网络安全</strong>：Security, Encryption, Firewall, Authentication, Authorization</li><li><strong>面向对象设计</strong>：Class, Object, Inheritance, Polymorphism, Interface</li><li><strong>算法与数据结构</strong>：Algorithm, Complexity, Sorting, Searching, Recursion</li></ol><h3 id="_3-词汇记忆方法" tabindex="-1">3. 词汇记忆方法 <a class="header-anchor" href="#_3-词汇记忆方法" aria-label="Permalink to &quot;3. 词汇记忆方法&quot;">​</a></h3><ul><li><strong>分类记忆</strong>：按主题分类（软件工程、数据库、网络等）</li><li><strong>联想记忆</strong>：将英文词汇与中文含义建立联系</li><li><strong>例句记忆</strong>：结合例句理解词汇用法</li><li><strong>反复复习</strong>：使用艾宾浩斯记忆曲线规律复习</li></ul><hr><h2 id="六、真题示例与解析" tabindex="-1">六、真题示例与解析 <a class="header-anchor" href="#六、真题示例与解析" aria-label="Permalink to &quot;六、真题示例与解析&quot;">​</a></h2><h3 id="真题1-2023年上半年" tabindex="-1">真题1（2023年上半年） <a class="header-anchor" href="#真题1-2023年上半年" aria-label="Permalink to &quot;真题1（2023年上半年）&quot;">​</a></h3><p><strong>原文片段</strong>：</p><blockquote><p>The Agile methodology emphasizes flexibility and customer collaboration. It breaks projects into small increments called <strong><strong>(71)</strong></strong>, which are typically completed in 2-4 weeks. Each increment includes planning, requirements analysis, design, implementation, testing, and <strong><strong>(72)</strong></strong>. The team reviews progress at the end of each increment and adjusts the plan accordingly.</p></blockquote><p><strong>选项</strong>：</p><ul><li>(71) A) Sprints B) Phases C) Cycles D) Stages</li><li>(72) A) delivery B) documentation C) deployment D) debugging</li></ul><p><strong>答案与解析</strong>：</p><ul><li>(71) <strong>A) Sprints</strong>：Scrum框架中的迭代周期称为Sprint，通常2-4周</li><li>(72) <strong>C) deployment</strong>：敏捷开发的每个迭代包括部署阶段</li></ul><h3 id="真题2-2022年下半年" tabindex="-1">真题2（2022年下半年） <a class="header-anchor" href="#真题2-2022年下半年" aria-label="Permalink to &quot;真题2（2022年下半年）&quot;">​</a></h3><p><strong>原文片段</strong>：</p><blockquote><p>In object-oriented programming, a <strong><strong>(71)</strong></strong> is a template for creating objects. It defines a set of attributes and methods that the objects will have. <strong><strong>(72)</strong></strong> allows a class to inherit properties and methods from another class, promoting code reuse.</p></blockquote><p><strong>选项</strong>：</p><ul><li>(71) A) object B) class C) method D) attribute</li><li>(72) A) Encapsulation B) Polymorphism C) Inheritance D) Abstraction</li></ul><p><strong>答案与解析</strong>：</p><ul><li>(71) <strong>B) class</strong>：类是创建对象的模板</li><li>(72) <strong>C) Inheritance</strong>：继承允许类从另一个类继承属性和方法</li></ul><hr><h2 id="七、备考建议" tabindex="-1">七、备考建议 <a class="header-anchor" href="#七、备考建议" aria-label="Permalink to &quot;七、备考建议&quot;">​</a></h2><h3 id="_1-每日背诵计划" tabindex="-1">1. 每日背诵计划 <a class="header-anchor" href="#_1-每日背诵计划" aria-label="Permalink to &quot;1. 每日背诵计划&quot;">​</a></h3><ul><li>每天背诵10-15个专业词汇</li><li>重点记忆高频词汇和固定搭配</li></ul><h3 id="_2-真题演练" tabindex="-1">2. 真题演练 <a class="header-anchor" href="#_2-真题演练" aria-label="Permalink to &quot;2. 真题演练&quot;">​</a></h3><ul><li>至少做近5年的英语真题</li><li>分析错题原因，总结规律</li></ul><h3 id="_3-阅读练习" tabindex="-1">3. 阅读练习 <a class="header-anchor" href="#_3-阅读练习" aria-label="Permalink to &quot;3. 阅读练习&quot;">​</a></h3><ul><li>阅读计算机专业英文文档</li><li>关注IT行业英文资讯</li></ul><h3 id="_4-模拟测试" tabindex="-1">4. 模拟测试 <a class="header-anchor" href="#_4-模拟测试" aria-label="Permalink to &quot;4. 模拟测试&quot;">​</a></h3><ul><li>模拟考试环境，限时完成</li><li>提高答题速度和准确率</li></ul><hr><h2 id="八、总结" tabindex="-1">八、总结 <a class="header-anchor" href="#八、总结" aria-label="Permalink to &quot;八、总结&quot;">​</a></h2><p>专业英语部分虽然只有5分，但掌握好这部分内容可以提高整体通过率。关键在于：</p><ol><li><strong>词汇积累</strong>：重点掌握计算机专业高频词汇</li><li><strong>语境理解</strong>：学会根据上下文推断词义</li><li><strong>语法基础</strong>：掌握基本语法结构和固定搭配</li><li><strong>真题训练</strong>：通过真题熟悉考试形式和出题规律</li></ol><p>只要认真准备，这5分完全可以轻松拿下！</p>',92)])])}const b=r(n,[["render",a]]);export{u as __pageData,b as default};
